"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[33191],{84719:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"SturmlanzeController","desc":"Renders every placed Sturmlanze for all players. Keeps one `TurretRig`\\n(`TrainTurret`) per turret in `workspace.PlacedObjects`, eases it toward the\\nreplicated `AimYaw` / `AimPitch`, and draws the beam (`BeamFx`) from the\\nrig\'s own muzzle: a turret shows its beam while `Firing` is true, read from the\\nattribute every frame, so a late joiner sees the current width at once. The\\nlocal gunner of a turret shows it from the trigger instead (prediction), along\\nits aim clamped into the aim cone like the server, and hears the looped beam\\nsound; the loop stops on release, overheat or leaving the turret. Every client\\nplays `StartSound` when `Firing` turns true and `OverheatSound` when\\n`Overheated` turns true, at the turret. `Gunner` gets each turret\'s mount\\nprompt, and its step runs first in the per-frame order.","realm":["Client"],"source":{"line":18,"path":"src/StarterPlayer/StarterPlayerScripts/SturmlanzeController/init.client.luau"}}')}}]);